// =========================================================================
// MESIN OTOMASI MYSIMS TAHAP 100 (2-STAGE GOLD STANDARD)
// 1. Login & Cookie Jar Deduplication
// 2. Cek Agenda Tertinggi Sebelum Submit (maxAgendaBefore)
// 3. Submit Surat Keluar Baru (act_add) -> Terbit Nomor Baru (misal 1085)
// 4. Scrape Baris Baru (agenda > maxAgendaBefore) + Link Edit (/edt/<idp>)
// 5. Scrape Form Edit Eksisting (Field Nilai Asli + Sifat 'Biasa' + Nama Input File)
// 6. Callback ke TRANSKEP Produksi -> Simpan Nomor 1085 & Terima PDF Bernomor 1085
// 7. Siapkan Binary File Native n8n (prepareBinaryData) untuk Node 3 Multipart
// =========================================================================

const VERIFIED_GAS_URL = 'https://script.google.com/macros/s/AKfycbzFrbQTqmVzMio7mderK-S9ntFVjXiWYFgnXfy9fW_SUKOcIxfPywP2He1flhaK_AZ0ZA/exec';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) TRANSKEP-Bot/2.0';

const webhookData = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json || {};
const cutiId = String(webhookData.cuti_id || '').trim();
const namaPegawai = String(webhookData.nama_pegawai || 'Pegawai').trim();
const jenisCuti = String(webhookData.jenis_cuti || 'Tahunan').trim();
const callbackUrl = String(webhookData.callback_url || VERIFIED_GAS_URL).trim() || VERIFIED_GAS_URL;
const secretKey = String(webhookData.secret_key || 'TRANSKEP_WA_BOT_2026').trim();

const mysims = webhookData.mysims_payload || {};
const dari = String(mysims.dari || namaPegawai).trim();
const uraian = String(mysims.uraian || ('Permohonan Cuti ' + jenisCuti + ' a.n. ' + namaPegawai)).trim();
const kode = String(mysims.kode || 'KP5.3').trim();
const tglSurat = String(mysims.tgl_surat || new Date().toISOString().slice(0, 10)).trim();
const ket = String(mysims.ket || ('cuti ' + jenisCuti.toLowerCase())).trim();

const cleanFirst = dari.replace(/[^a-zA-Z0-9]/g, ' ').trim().split(/\s+/)[0].toLowerCase() || 'pegawai';
let pdfFileName = String(webhookData.pdf_filename || ('TRANSKEP_' + cleanFirst + '_ct.pdf')).trim();
let pdfBase64 = String(webhookData.pdf_base64 || '').trim();

const debugLog = [];
const cookieJar = {};

const updateCookies = (headers) => {
  if (!headers) return;
  const raw = headers['set-cookie'] || headers['Set-Cookie'] || [];
  const list = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  for (const item of list) {
    const pair = String(item).split(';')[0].trim();
    const eqIdx = pair.indexOf('=');
    if (eqIdx > 0) {
      const k = pair.slice(0, eqIdx).trim();
      const v = pair.slice(eqIdx + 1).trim();
      if (v && v.toLowerCase() !== 'deleted') {
        cookieJar[k] = v;
      }
    }
  }
};

const getCookieHeader = () => Object.keys(cookieJar).map(k => k + '=' + cookieJar[k]).join('; ');

const decodeHtmlEntities = (s) => String(s || '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#0*39;/g, "'");

const resolveMysimsUrl = (u) => {
  if (!u) return '';
  const clean = decodeHtmlEntities(u).trim();
  if (/^https?:\/\//i.test(clean)) return clean;
  if (clean.startsWith('/')) return 'http://192.168.188.10' + clean;
  if (clean.startsWith('index.php')) return 'http://192.168.188.10/mysim/' + clean;
  return 'http://192.168.188.10/mysim/index.php/admin/' + clean.replace(/^admin\//i, '');
};

const parseSuratKeluarRows = (html) => {
  const rows = [];
  const trRegex = /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;
  let trM;
  while ((trM = trRegex.exec(html)) !== null) {
    const rowHtml = trM[1];
    const noMatch = rowHtml.match(/(\d+)\/(KPA\.W10-A2\/[A-Za-z0-9.]+\/[IVXLCDM]+\/\d{4})/i);
    if (!noMatch) continue;
    const agendaNum = parseInt(noMatch[1], 10);
    const fullNomor = noMatch[1] + '/' + noMatch[2];

    let editHref = '';
    let rowIdp = '';
    const edtMatch = rowHtml.match(/href=["']([^"']*\/surat_keluar\/edt\/([^"'/?#]+)[^"']*)["']/i);
    if (edtMatch) {
      editHref = edtMatch[1].trim();
      rowIdp = edtMatch[2].trim();
    }
    const plainText = decodeHtmlEntities(rowHtml.replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
    rows.push({
      agendaNum: isNaN(agendaNum) ? 0 : agendaNum,
      agendaStr: noMatch[1],
      nomorSurat: fullNomor,
      editHref: editHref,
      idp: rowIdp,
      plainText: plainText
    });
  }
  return rows;
};

// -------------------------------------------------------------------------
// LANGKAH 1: LOGIN KE MYSIMS
// -------------------------------------------------------------------------
try {
  const loginBody = 'u=' + encodeURIComponent('ketua') + '&p=' + encodeURIComponent('admin') + '&ta=' + encodeURIComponent('2026');
  const loginResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/do_login',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': UA
    },
    body: loginBody,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 8000
  });
  updateCookies(loginResp.headers);
  debugLog.push('1.Login:' + (getCookieHeader() ? 'OK' : 'NO_COOKIE'));
} catch (errLogin) {
  debugLog.push('1.LoginErr:' + errLogin.message);
}

// -------------------------------------------------------------------------
// LANGKAH 2: CEK DAFTAR SURAT AWAL (Catat maxAgendaBefore)
// -------------------------------------------------------------------------
let maxAgendaBefore = 0;
try {
  const initResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    headers: { 'Cookie': getCookieHeader(), 'User-Agent': UA },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 8000
  });
  updateCookies(initResp.headers);
  const initHtml = String(initResp.body || initResp.data || '');
  const initRows = parseSuratKeluarRows(initHtml);
  for (const r of initRows) {
    if (r.agendaNum > maxAgendaBefore) maxAgendaBefore = r.agendaNum;
  }
  debugLog.push('2.MaxBefore:' + maxAgendaBefore);
} catch (errInit) {
  debugLog.push('2.InitErr:' + errInit.message);
}

// -------------------------------------------------------------------------
// LANGKAH 3: SUBMIT SURAT KELUAR BARU (act_add via x-www-form-urlencoded)
// -------------------------------------------------------------------------
try {
  const addParams = {
    idp: '',
    no_agenda: '',
    dari: dari,
    no_surat: 'KPA.W10-A2/',
    uraian: uraian,
    kode: kode,
    tgl_surat: tglSurat,
    sifat: 'Biasa',
    ket: ket,
    submit: 'Simpan'
  };
  const addBody = Object.keys(addParams)
    .map(k => encodeURIComponent(k) + '=' + encodeURIComponent(addParams[k]))
    .join('&');

  const addResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/act_add',
    headers: {
      'Cookie': getCookieHeader(),
      'Content-Type': 'application/x-www-form-urlencoded',
      'User-Agent': UA
    },
    body: addBody,
    disableFollowRedirect: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 8000
  });
  updateCookies(addResp.headers);
  debugLog.push('3.AddStatus:' + (addResp.statusCode || addResp.status));
} catch (errAdd) {
  debugLog.push('3.AddErr:' + errAdd.message);
}

// -------------------------------------------------------------------------
// LANGKAH 4: SCRAPE BARIS BARU (agendaNum > maxAgendaBefore) & LINK EDIT
// -------------------------------------------------------------------------
let nomorSurat = '';
let targetNewRow = null;
try {
  const afterResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    headers: { 'Cookie': getCookieHeader(), 'User-Agent': UA },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 8000
  });
  updateCookies(afterResp.headers);
  const afterHtml = String(afterResp.body || afterResp.data || '');
  const afterRows = parseSuratKeluarRows(afterHtml);

  const dariKey = cleanFirst.toLowerCase();
  targetNewRow = afterRows.find(r => r.agendaNum > maxAgendaBefore && r.plainText.toLowerCase().includes(dariKey))
    || afterRows.find(r => r.agendaNum > maxAgendaBefore)
    || (maxAgendaBefore === 0 && afterRows.length > 0 ? afterRows[0] : null);

  if (targetNewRow) {
    nomorSurat = targetNewRow.nomorSurat;
    debugLog.push('4.NewRow:' + nomorSurat + '(idp=' + (targetNewRow.idp || '?') + ')');
  } else {
    debugLog.push('4.NewRow:NOT_FOUND(rows=' + afterRows.length + ')');
  }
} catch (errAfter) {
  debugLog.push('4.AfterErr:' + errAfter.message);
}

// -------------------------------------------------------------------------
// LANGKAH 5: BUKA HALAMAN EDIT (/edt/<idp>) UNTUK AMBIL ACTION & FIELD ASLI
// -------------------------------------------------------------------------
let editPageUrl = targetNewRow && targetNewRow.editHref ? resolveMysimsUrl(targetNewRow.editHref) : '';
let editActionUrl = 'http://192.168.188.10/mysim/index.php/admin/surat_keluar/act_edt';
let fileFieldName = 'file_surat';
let sifatFieldName = 'sifat';
let sifatVal = 'Biasa';
const scrapedInputs = {};

if (editPageUrl) {
  try {
    const edtResp = await this.helpers.httpRequest({
      method: 'GET',
      url: editPageUrl,
      headers: { 'Cookie': getCookieHeader(), 'User-Agent': UA },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 5000
    });
    updateCookies(edtResp.headers);
    const edtHtml = String(edtResp.body || edtResp.data || '');

    // Pilih <form> utama Edit Surat Keluar (abaikan form pencarian di header)
    let targetFormHtml = edtHtml;
    const formRegex = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
    let fMatch;
    while ((fMatch = formRegex.exec(edtHtml)) !== null) {
      const fAttrs = fMatch[1] || '';
      const fBody = fMatch[2] || '';
      if (/act_edt|multipart\/form-data/i.test(fAttrs) || /name=["'](dari|uraian|file_surat)["']/i.test(fBody)) {
        targetFormHtml = fBody;
        const actM = fAttrs.match(/\baction=["']([^"']+)["']/i);
        if (actM && actM[1]) {
          editActionUrl = resolveMysimsUrl(actM[1]);
        }
        break;
      }
    }

    // Ekstrak seluruh <input>
    const inputRegex = /<input\b([^>]*)>/gi;
    let inpM;
    while ((inpM = inputRegex.exec(targetFormHtml)) !== null) {
      const attrs = inpM[1] || '';
      const typeM = attrs.match(/\btype=["']([^"']+)["']/i);
      const inpType = (typeM ? typeM[1] : 'text').toLowerCase().trim();
      const nameM = attrs.match(/\bname=["']([^"']+)["']/i);
      if (!nameM) continue;
      const inpName = nameM[1].trim();
      if (inpType === 'file') {
        fileFieldName = inpName;
        continue;
      }
      if (inpType === 'submit' || inpType === 'button' || inpType === 'reset' || inpType === 'image') continue;
      const valM = attrs.match(/\bvalue=["']([^"']*)["']/i);
      scrapedInputs[inpName] = valM ? decodeHtmlEntities(valM[1]) : '';
    }

    // Ekstrak seluruh <textarea>
    const taRegex = /<textarea\b([^>]*)>([\s\S]*?)<\/textarea>/gi;
    let taM;
    while ((taM = taRegex.exec(targetFormHtml)) !== null) {
      const nameM = (taM[1] || '').match(/\bname=["']([^"']+)["']/i);
      if (!nameM) continue;
      scrapedInputs[nameM[1].trim()] = decodeHtmlEntities(taM[2] || '').trim();
    }

    // Ekstrak <select> Sifat & nilai eksak opsi 'Biasa'
    const selectRegex = /<select\b([^>]*)>([\s\S]*?)<\/select>/gi;
    let selM;
    while ((selM = selectRegex.exec(targetFormHtml)) !== null) {
      const attrs = selM[1] || '';
      const inner = selM[2] || '';
      const nameM = attrs.match(/\bname=["']([^"']+)["']/i);
      if (!nameM) continue;
      const selName = nameM[1].trim();
      if (/sifat/i.test(selName) || /biasa/i.test(inner)) {
        sifatFieldName = selName;
        const optRegex = /<option\b([^>]*)>([\s\S]*?)<\/option>/gi;
        let optM;
        while ((optM = optRegex.exec(inner)) !== null) {
          const optAttrs = optM[1] || '';
          const optText = decodeHtmlEntities(String(optM[2] || '').replace(/<[^>]*>/g, '')).trim();
          const valM = optAttrs.match(/\bvalue=["']([^"']*)["']/i);
          const optVal = valM ? decodeHtmlEntities(valM[1]).trim() : optText;
          if (/^biasa$/i.test(optText) || /^biasa$/i.test(optVal)) {
            sifatVal = optVal || 'Biasa';
            break;
          }
        }
      }
    }
    debugLog.push('5.EditForm:OK(act=' + editActionUrl.split('/').slice(-2).join('/') + ',file=' + fileFieldName + ',sifat=' + sifatFieldName + ':' + sifatVal + ')');
  } catch (errEdt) {
    debugLog.push('5.EditFormErr:' + errEdt.message);
  }
}

// -------------------------------------------------------------------------
// LANGKAH 6: CALLBACK KE TRANSKEP (Simpan Nomor 1085 + Ambil PDF Bernomor 1085)
// -------------------------------------------------------------------------
let callbackOk = false;
const parseCbBody = (raw) => {
  if (!raw) return null;
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(String(raw)); } catch (e) { return null; }
};

if (nomorSurat && cutiId) {
  // 6A. Coba POST dengan penanganan manual Redirect 302 Google Apps Script (POST -> GET Location)
  try {
    const cbPost = await this.helpers.httpRequest({
      method: 'POST',
      url: callbackUrl,
      headers: { 'Content-Type': 'application/json', 'User-Agent': UA },
      body: JSON.stringify({
        action: 'updateNomorSuratCuti',
        id: cutiId,
        nomor_surat: nomorSurat,
        nama_pegawai: namaPegawai,
        secret_key: secretKey
      }),
      disableFollowRedirect: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 25000
    });

    const stCode = Number(cbPost.statusCode || cbPost.status || 0);
    const locUrl = cbPost.headers ? (cbPost.headers.location || cbPost.headers.Location) : '';
    let cbJson = null;

    if ((stCode === 301 || stCode === 302 || stCode === 303 || stCode === 307 || stCode === 308) && locUrl) {
      const echoResp = await this.helpers.httpRequest({
        method: 'GET',
        url: locUrl,
        headers: { 'User-Agent': UA },
        disableFollowRedirect: false,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 25000
      });
      cbJson = parseCbBody(echoResp.body || echoResp.data);
    } else {
      cbJson = parseCbBody(cbPost.body || cbPost.data);
    }

    if (cbJson && cbJson.status === 'success') {
      callbackOk = true;
      if (cbJson.pdf_base64 && String(cbJson.pdf_base64).length > 100) {
        pdfBase64 = String(cbJson.pdf_base64);
      }
      if (cbJson.pdf_filename) pdfFileName = String(cbJson.pdf_filename);
      debugLog.push('6.CallbackPOST:OK(pdfB64=' + pdfBase64.length + ')');
    } else {
      debugLog.push('6.CallbackPOST:NON_SUCCESS(st=' + stCode + ')');
    }
  } catch (errCbPost) {
    debugLog.push('6.CallbackPOSTErr:' + errCbPost.message);
  }

  // 6B. Fallback GET otomatis jika POST belum sukses atau pdfBase64 masih kosong
  if (!callbackOk || !pdfBase64 || pdfBase64.length < 100) {
    try {
      const sep = callbackUrl.includes('?') ? '&' : '?';
      const getUrl = callbackUrl + sep +
        'api=true&action=updateNomorSuratCuti' +
        '&id=' + encodeURIComponent(cutiId) +
        '&nomor_surat=' + encodeURIComponent(nomorSurat) +
        '&nama_pegawai=' + encodeURIComponent(namaPegawai) +
        '&secret_key=' + encodeURIComponent(secretKey);

      const cbGet = await this.helpers.httpRequest({
        method: 'GET',
        url: getUrl,
        headers: { 'User-Agent': UA },
        disableFollowRedirect: false,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 25000
      });
      const cbGetJson = parseCbBody(cbGet.body || cbGet.data);
      if (cbGetJson && cbGetJson.status === 'success') {
        callbackOk = true;
        if (cbGetJson.pdf_base64 && String(cbGetJson.pdf_base64).length > 100) {
          pdfBase64 = String(cbGetJson.pdf_base64);
        }
        if (cbGetJson.pdf_filename) pdfFileName = String(cbGetJson.pdf_filename);
        debugLog.push('6B.CallbackGET:OK(pdfB64=' + pdfBase64.length + ')');
      } else {
        debugLog.push('6B.CallbackGET:FAIL');
      }
    } catch (errCbGet) {
      debugLog.push('6B.CallbackGETErr:' + errCbGet.message);
    }
  }
} else {
  debugLog.push('6.CallbackSkipped(noSurat=' + (nomorSurat || 'EMPTY') + ')');
}

// -------------------------------------------------------------------------
// LANGKAH 7: SIAPKAN FORM EDIT & BINARY FILE NATIVE n8n UNTUK NODE 3
// -------------------------------------------------------------------------
const finalIdp = String(scrapedInputs.idp || (targetNewRow && targetNewRow.idp) || '').trim();
const finalNoAgenda = String(scrapedInputs.no_agenda || (targetNewRow && targetNewRow.agendaStr) || '').trim();
const finalNoSurat = (scrapedInputs.no_surat !== undefined && String(scrapedInputs.no_surat).trim() !== '')
  ? String(scrapedInputs.no_surat).trim()
  : nomorSurat;

const formFields = {
  idp: finalIdp,
  no_agenda: finalNoAgenda,
  dari: scrapedInputs.dari || dari,
  no_surat: finalNoSurat,
  uraian: scrapedInputs.uraian || uraian,
  kode: scrapedInputs.kode || kode,
  tgl_surat: scrapedInputs.tgl_surat || tglSurat,
  sifat: sifatVal,
  ket: scrapedInputs.ket || ket
};

if (!pdfBase64 || pdfBase64.length < 100 || !finalIdp) {
  debugLog.push('7.SkipBinary(idp=' + finalIdp + ',b64=' + (pdfBase64 ? pdfBase64.length : 0) + ')');
  return [];
}

const pdfBuffer = Buffer.from(pdfBase64, 'base64');
const binaryFile = await this.helpers.prepareBinaryData(pdfBuffer, pdfFileName, 'application/pdf');
debugLog.push('7.BinaryReady:' + pdfFileName + '(' + pdfBuffer.length + 'B)');

return [{
  json: {
    cuti_id: cutiId,
    nomor_surat: nomorSurat,
    idp: finalIdp,
    editPageUrl: editPageUrl || 'http://192.168.188.10/mysim/index.php/admin/surat_keluar',
    editActionUrl: editActionUrl,
    sessionCookie: getCookieHeader(),
    fileFieldName: fileFieldName,
    sifatFieldName: sifatFieldName,
    formFields: formFields,
    pdf_filename: pdfFileName,
    pdf_size_bytes: pdfBuffer.length,
    callback_ok: callbackOk,
    debug_log: debugLog.join(' | ')
  },
  binary: {
    file_surat: binaryFile
  }
}];
